        var chosen = ChooseResource(job, resources);
        placements.Add(chosen == null
            ? $"{job.Id}:UNPLACED"
            : FormatPlacement(job, chosen));
    }

    return placements;
}

private static Resource? ChooseResource(Job job, IEnumerable<Resource> resources)
{
