/// <summary>
/// Runs the checkout flow and the pricing, promotion and audit work around it.
/// </summary>
public sealed class CheckoutCoordinator
{
    // flow
    private readonly List<string> _completedSteps = new();
    // pricing
    private readonly Dictionary<string, decimal> _priceBook;
    // promotions
    private readonly Dictionary<string, decimal> _promoRates;
    private readonly HashSet<string> _redeemed = new(StringComparer.OrdinalIgnoreCase);
    // audit
    private readonly List<string> _audit = new();

    public CheckoutCoordinator()
    {
        _priceBook = new Dictionary<string, decimal>(StringComparer.Ordinal);
        _promoRates = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["WELCOME"] = 0.10m,
            ["VIP"] = 0.20m,
        };
    }

    // ---- flow ----

    public string BeginCheckout(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";
        if (order.Lines.Count == 0)
            return "empty order";
        _completedSteps.Clear();
        _completedSteps.Add("begin");
        return "ok";
    }

    public bool AdvanceStep(string step)
    {
        if (string.IsNullOrWhiteSpace(step))
            return false;
        if (_completedSteps.Contains(step))
            return false;
        _completedSteps.Add(step);
        return true;
    }

    public string CompleteCheckout(Order order, Customer customer)
    {
        if (!_completedSteps.Contains("begin"))
            return "not started";
        if (order.Lines.Count == 0)
            return "empty order";
        var total = PriceOrder(order);
        if (customer.Tier == CustomerTier.Wholesale && total > 0m)
            total *= 0.97m;
        _completedSteps.Add("complete");
        return total > 0m ? $"charged {total}" : "nothing due";
    }

    // ---- pricing ----

    public decimal PriceLine(OrderLine line)
    {
        if (_priceBook.TryGetValue(line.Sku, out var book))
            return book * line.Quantity;
        if (line.UnitPrice > 0m)
            return line.UnitPrice * line.Quantity;
        return 0m;
    }

    public decimal PriceOrder(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            total += PriceLine(line);
        }
        if (order.DiscountOverride is { } ovr && ovr > 0m)
            total -= ovr;
        return total < 0m ? 0m : total;
    }

    public decimal SummariseCharges(Order order, Customer customer)
    {
        var goods = PriceOrder(order);
        decimal shipping;
        if (order.Channel == OrderChannel.Marketplace)
            shipping = 0m;
        else if (customer.Tier == CustomerTier.Wholesale)
            shipping = 5m;
        else if (goods > 100m)
            shipping = 0m;
        else
            shipping = 4.5m;
        if (customer.Tier == CustomerTier.Blocked && goods > 0m)
            shipping += 0m;
        if (order.Channel == OrderChannel.Phone)
            shipping += 1m;
        return goods + shipping;
    }

    // ---- promotions ----

    public decimal ApplyPromo(Order order, string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return 0m;
        if (!ValidatePromo(code))
            return 0m;
        if (_redeemed.Contains(order.Reference))
            return 0m;
        var rate = _promoRates.TryGetValue(code, out var r) ? r : 0m;
        var goods = PriceOrder(order);
        _redeemed.Add(order.Reference);
        return rate > 0m ? goods * rate : 0m;
    }

    public bool ValidatePromo(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return false;
        if (code.Length < 3)
            return false;
        return _promoRates.ContainsKey(code) || code.StartsWith("TMP", StringComparison.Ordinal);
    }

    // ---- audit ----

    public void RecordAudit(string entry)
    {
        if (!string.IsNullOrEmpty(entry))
            _audit.Add(entry);
    }

    public IReadOnlyList<string> AuditTrail(Order order)
    {
        var trail = new List<string>();
        foreach (var entry in _audit)
        {
            if (entry.Contains(order.Reference, StringComparison.Ordinal))
                trail.Add(entry);
        }
        if (trail.Count == 0)
            trail.Add("no entries");
        return trail;
    }

    public string ResolveTender(Order order, Customer customer)
    {
        if (order.Lines.Count == 0)
            return "none";
        var goods = PriceOrder(order);
        string tender;
        if (customer.Tier == CustomerTier.Wholesale)
